const input = $input.first().json;

const profile = input.student_profile || {};

const specialization =
  profile.mba_specialization ||
  "MBA";

const locations = Array.isArray(profile.preferred_locations)
  ? profile.preferred_locations.filter(Boolean)
  : [];

const locationText =
  locations.length > 0
    ? locations.join(" ")
    : "India";

const queries = [
  {
    query_type: "location_program",
    search_query:
      `MBA ${specialization} colleges in ${locationText} India`
  },
  {
    query_type: "official_programs",
    search_query:
      `MBA ${specialization} university institute programs ${locationText} India`
  },
  {
    query_type: "admission_candidates",
    search_query:
      `MBA ${specialization} colleges admission ${locationText} India`
  }
];

return queries.map((q, index) => ({
  json: {
    session_id: input.session_id || null,

    student_profile: profile,

    query_number: index + 1,

    query_type: q.query_type,

    search_query: q.search_query
  }
}));

// ============================================================
// EDUCOMPASS — PREPARE CANDIDATE POOL
// Collect all Tavily results and restore the student profile
// from BUILD — DISCOVERY QUERIES.
// ============================================================

const items = $input.all();

const candidateResults = [];

// ------------------------------------------------------------
// IMPORTANT:
// Tavily output does not preserve the student_profile.
// Get it directly from the discovery-query node.
// ------------------------------------------------------------

let studentProfile = {};

try {
  studentProfile =
    $('BUILD — DISCOVERY QUERIES').first().json.student_profile
    || {};
} catch (error) {
  studentProfile = {};
}

// ------------------------------------------------------------
// Collect all Tavily results
// ------------------------------------------------------------

for (const item of items) {
  const data = item.json || {};

  // Direct result
  if (data.url || data.title) {
    candidateResults.push({
      title: data.title || "",
      url: data.url || "",
      snippet:
        data.snippet ||
        data.content ||
        data.raw_content ||
        "",
      search_score:
        data.search_score ??
        data.score ??
        null,
      query_number: data.query_number ?? null,
      query_type: data.query_type ?? null
    });
  }

  // Tavily results array
  if (Array.isArray(data.results)) {
    for (const result of data.results) {
      if (!result || typeof result !== "object") {
        continue;
      }

      candidateResults.push({
        title: result.title || "",
        url: result.url || "",
        snippet:
          result.snippet ||
          result.content ||
          result.raw_content ||
          "",
        search_score:
          result.search_score ??
          result.score ??
          null,
        query_number: result.query_number ?? null,
        query_type: result.query_type ?? null
      });
    }
  }

  // Nested data.results
  if (
    data.data &&
    typeof data.data === "object" &&
    Array.isArray(data.data.results)
  ) {
    for (const result of data.data.results) {
      if (!result || typeof result !== "object") {
        continue;
      }

      candidateResults.push({
        title: result.title || "",
        url: result.url || "",
        snippet:
          result.snippet ||
          result.content ||
          result.raw_content ||
          "",
        search_score:
          result.search_score ??
          result.score ??
          null,
        query_number: result.query_number ?? null,
        query_type: result.query_type ?? null
      });
    }
  }
}

// ------------------------------------------------------------
// Remove results without URLs
// ------------------------------------------------------------

const usableResults = candidateResults.filter(
  candidate =>
    typeof candidate.url === "string" &&
    candidate.url.trim() !== ""
);

// ------------------------------------------------------------
// Deduplicate URLs
// ------------------------------------------------------------

const seen = new Set();
const deduplicated = [];

for (const candidate of usableResults) {
  const key = candidate.url
    .trim()
    .toLowerCase()
    .replace(/\/$/, "");

  if (seen.has(key)) {
    continue;
  }

  seen.add(key);
  deduplicated.push(candidate);
}

// ------------------------------------------------------------
// Sort by Tavily relevance
// ------------------------------------------------------------

deduplicated.sort((a, b) => {
  const scoreA =
    typeof a.search_score === "number"
      ? a.search_score
      : 0;

  const scoreB =
    typeof b.search_score === "number"
      ? b.search_score
      : 0;

  return scoreB - scoreA;
});

// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {
      session_id:
        $('BUILD — DISCOVERY QUERIES').first().json.session_id
        || null,

      student_profile: studentProfile,

      candidate_results: deduplicated,

      candidate_count: deduplicated.length
    }
  }
];

