const items = $input.all();

return items.map(item => {
  const raw = item.json.output;

  if (typeof raw !== 'string') {
    throw new Error(
      'Agent 1 output is not a string.'
    );
  }

  let text = raw.trim();

  // Remove accidental Markdown code fences.
  text = text.replace(/^```json\s*/i, '');
  text = text.replace(/^```\s*/i, '');
  text = text.replace(/\s*```$/i, '');
  text = text.trim();

  let parsed;

  try {
    parsed = JSON.parse(text);
  } catch (error) {
    throw new Error(
      `Invalid JSON returned by Agent 1: ${error.message}\n\nRaw output:\n${text}`
    );
  }

  return {
    json: parsed
  };
});

// ============================================================
// EDUCOMPASS — FINAL RESEARCH QUERY BUILDER
//
// 12 selected colleges
// 3 focused searches per college
// Total = 36 Tavily items
//
// The source restriction is written directly into the query.
// This avoids unreliable dynamic Tavily include_domains mapping.
// ============================================================

const input =
  $input.first()?.json || {};

const studentProfile =
  input.student_profile || {};

const candidates =
  Array.isArray(input.candidates)
    ? input.candidates
    : [];

const output = [];

function clean(value) {

  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim();
}


// ============================================================
// OFFICIAL DOMAIN MAP
// Used when the candidate does not already have a domain.
// ============================================================

const officialDomainMap = {

  "Indira University":
    "indirauniversity.edu.in",

  "MIT-WPU":
    "mitwpu.edu.in",

  "IIM Bangalore":
    "iimb.ac.in",

  "Amrita Vishwa Vidyapeetham":
    "amrita.edu",

  "SCMHRD Pune":
    "scmhrd.edu",

  "JSPM University":
    "jspmuni.ac.in",

  "New Horizon College of Engineering":
    "newhorizoncollegeofengineering.in",

  "Dayananda Sagar Business School":
    "dsbs.edu.in",

  "Christ University":
    "christuniversity.in",

  "JAGSoM":
    "jagsom.edu.in",

  "BITS Pilani WILP":
    "bits-pilani-wilp.ac.in",

  "NMIMS":
    "nmims.edu"
};


function getInstitution(candidate) {

  return clean(
    candidate.institution ||
    candidate.institution_name ||
    candidate.title ||
    ""
  );
}


function getProgram(candidate) {

  const existing =
    clean(
      candidate.program ||
      candidate.program_name ||
      ""
    );

  if (existing) {
    return existing;
  }

  const specialization =
    clean(
      studentProfile.mba_specialization
    );

  return specialization
    ? `MBA in ${specialization}`
    : "MBA in Business Analytics";
}


function getLocation(candidate) {

  return clean(
    candidate.location ||
    candidate.city ||
    ""
  );
}


function getOfficialUrl(candidate) {

  return clean(
    candidate.official_url ||
    ""
  );
}


function getOfficialDomain(
  candidate,
  college
) {

  const supplied =
    clean(
      candidate.official_domain ||
      ""
    ).toLowerCase();

  if (supplied) {
    return supplied;
  }

  return (
    officialDomainMap[college] ||
    ""
  );
}


// ============================================================
// PROCESS SELECTED COLLEGES
// ============================================================

candidates.forEach(
  (candidate, index) => {

    const candidateIndex =
      candidate.candidate_index ??
      index + 1;

    const college =
      getInstitution(candidate);

    const program =
      getProgram(candidate);

    const city =
      getLocation(candidate);

    const officialUrl =
      getOfficialUrl(candidate);

    const officialDomain =
      getOfficialDomain(
        candidate,
        college
      );

    const selectionScore =
      candidate.selection_score ??
      null;


    // ========================================================
    // QUERY 1 — OFFICIAL ADMISSION
    // ========================================================

    let query1 =
      `"${college}" "${program}"`;

    if (city) {
      query1 += ` "${city}"`;
    }

    query1 +=
      ` MBA admission eligibility` +
      ` accepted entrance exams` +
      ` CAT XAT SNAP CMAT MAT GMAT NMAT` +
      ` admission criteria` +
      ` selection process GD PI WAT` +
      ` total MBA fees fee structure` +
      ` reservation category benefits` +
      ` specializations offered` +
      ` official admission policy`;

    if (officialDomain) {
      query1 +=
        ` site:${officialDomain}`;
    }


    output.push({
      json: {

        research_id:
          `${candidateIndex}_official_admission`,

        candidate_index:
          candidateIndex,

        query_number:
          1,

        query_type:
          "official_admission",

        source_type:
          "official",

        research_query:
          query1,

        official_domain:
          officialDomain,

        official_url:
          officialUrl,

        student_profile:
          studentProfile,

        college: {

          candidate_index:
            candidateIndex,

          institution:
            college,

          program:
            program,

          location:
            city,

          official_url:
            officialUrl,

          official_domain:
            officialDomain,

          selection_score:
            selectionScore
        }
      }
    });


    // ========================================================
    // QUERY 2 — OFFICIAL QUALITY / PLACEMENT
    // ========================================================

    let query2 =
      `"${college}" "${program}"`;

    if (city) {
      query2 += ` "${city}"`;
    }

    query2 +=
      ` MBA placement` +
      ` average placement package` +
      ` median placement package` +
      ` highest placement package` +
      ` placement percentage` +
      ` placement rate` +
      ` top recruiting companies` +
      ` recruiters` +
      ` curriculum syllabus` +
      ` faculty` +
      ` internships` +
      ` alumni network` +
      ` infrastructure` +
      ` industry exposure` +
      ` NIRF ranking` +
      ` accreditation AICTE UGC NAAC NBA AACSB AMBA EQUIS` +
      ` business analyst data analyst analytics consulting careers`;

    if (officialDomain) {
      query2 +=
        ` site:${officialDomain}`;
    }


    output.push({
      json: {

        research_id:
          `${candidateIndex}_official_quality`,

        candidate_index:
          candidateIndex,

        query_number:
          2,

        query_type:
          "official_quality_placement",

        source_type:
          "official",

        research_query:
          query2,

        official_domain:
          officialDomain,

        official_url:
          officialUrl,

        student_profile:
          studentProfile,

        college: {

          candidate_index:
            candidateIndex,

          institution:
            college,

          program:
            program,

          location:
            city,

          official_url:
            officialUrl,

          official_domain:
            officialDomain,

          selection_score:
            selectionScore
        }
      }
    });


    // ========================================================
    // QUERY 3 — THIRD-PARTY FALLBACK
    // ========================================================

    let query3 =
      `"${college}" "${program}"`;

    if (city) {
      query3 += ` "${city}"`;
    }

    query3 +=
      ` MBA cutoff 2025` +
      ` MBA cutoff 2024` +
      ` exam wise cutoff percentile` +
      ` CAT cutoff XAT cutoff SNAP cutoff CMAT cutoff` +
      ` MAT cutoff GMAT cutoff NMAT cutoff` +
      ` historical cutoff` +
      ` total MBA fees` +
      ` average placement package` +
      ` median placement package` +
      ` highest placement package` +
      ` placement percentage`;

    // Literal source restriction.
    query3 +=
      ` site:collegedunia.com`;


    output.push({
      json: {

        research_id:
          `${candidateIndex}_third_party_fallback`,

        candidate_index:
          candidateIndex,

        query_number:
          3,

        query_type:
          "third_party_fallback",

        source_type:
          "third_party",

        research_query:
          query3,

        official_domain:
          officialDomain,

        official_url:
          officialUrl,

        student_profile:
          studentProfile,

        college: {

          candidate_index:
            candidateIndex,

          institution:
            college,

          program:
            program,

          location:
            city,

          official_url:
            officialUrl,

          official_domain:
            officialDomain,

          selection_score:
            selectionScore
        }
      }
    });

  }
);


// ============================================================
// FINAL OUTPUT
// ============================================================

return output;

