parameters.jsCode:
// ============================================================
// EDUCOMPASS — PREPARE VERIFIED EVIDENCE
//
// IMPORTANT:
// Tavily does not preserve our Build-node metadata.
// Therefore we pair each Tavily response with the
// corresponding BUILD item by item index.
//
// BUILD:
// 36 items
//
// TAVILY:
// 36 items
//
// Result:
// 12 college bundles
// ============================================================

const tavilyItems = $input.all();

const buildItems =
  $("BUILD — COLLEGE RESEARCH QUERIES").all();


// ------------------------------------------------------------
// SAFETY CHECK
// ------------------------------------------------------------

if (buildItems.length !== tavilyItems.length) {

  throw new Error(
    `BUILD/TAVILY item count mismatch. ` +
    `BUILD=${buildItems.length}, ` +
    `TAVILY=${tavilyItems.length}`
  );
}


const collegeMap = new Map();

let studentProfile = {};


// ============================================================
// PROCESS EACH TAVILY RESULT
// ============================================================

tavilyItems.forEach(
  (tavilyItem, index) => {

    const tavily =
      tavilyItem.json || {};

    // --------------------------------------------------------
    // Recover metadata from the matching BUILD item
    // --------------------------------------------------------

    const build =
      buildItems[index]?.json || {};

    const collegeMeta =
      build.college || {};

    const candidateIndex =
      Number(
        build.candidate_index ??
        collegeMeta.candidate_index
      );

    if (!candidateIndex) {
      return;
    }


    // --------------------------------------------------------
    // Student profile
    // --------------------------------------------------------

    if (
      build.student_profile &&
      Object.keys(
        build.student_profile
      ).length
    ) {

      studentProfile =
        build.student_profile;
    }


    // --------------------------------------------------------
    // Create college bundle
    // --------------------------------------------------------

    if (
      !collegeMap.has(
        candidateIndex
      )
    ) {

      collegeMap.set(
        candidateIndex,
        {

          candidate_index:
            candidateIndex,

          institution:
            collegeMeta.institution ||
            "",

          program:
            collegeMeta.program ||
            "",

          location:
            collegeMeta.location ||
            "",

          official_url:
            collegeMeta.official_url ||
            "",

          official_domain:
            collegeMeta.official_domain ||
            "",

          selection_score:
            collegeMeta.selection_score ??
            null,

          official_admission_research:
            [],

          official_quality_research:
            [],

          third_party_fallback_research:
            []
        }
      );
    }


    const college =
      collegeMap.get(
        candidateIndex
      );


    // ========================================================
    // KEEP TAVILY RESEARCH EXACTLY AS RETURNED
    // ========================================================

    const research = {

      research_id:
        build.research_id ||
        "",

      candidate_index:
        candidateIndex,

      query_number:
        build.query_number ??
        null,

      query_type:
        build.query_type ||
        "",

      source_type:
        build.source_type ||
        "",

      research_query:
        build.research_query ||
        tavily.query ||
        "",

      official_domain:
        build.official_domain ||
        collegeMeta.official_domain ||
        "",

      results:
        Array.isArray(
          tavily.results
        )
          ? tavily.results.map(
              result => ({

                url:
                  result.url ||
                  "",

                title:
                  result.title ||
                  "",

                content:
                  result.content ||
                  "",

                score:
                  result.score ??
                  null
              })
            )
          : []
    };


    // ========================================================
    // PUT INTO CORRECT RESEARCH GROUP
    // ========================================================

    if (
      build.query_type ===
      "official_admission"
    ) {

      college
        .official_admission_research
        .push(
          research
        );

    }

    else if (
      build.query_type ===
      "official_quality_placement"
    ) {

      college
        .official_quality_research
        .push(
          research
        );

    }

    else if (
      build.query_type ===
      "third_party_fallback"
    ) {

      college
        .third_party_fallback_research
        .push(
          research
        );
    }

  }
);


// ============================================================
// SORT 12 COLLEGES
// ============================================================

const colleges =
  Array.from(
    collegeMap.values()
  ).sort(
    (a, b) =>
      a.candidate_index -
      b.candidate_index
  );


// ============================================================
// SAFETY CHECK
// ============================================================

if (colleges.length === 0) {

  throw new Error(
    "No college bundles were created. " +
    "Check BUILD/TAVILY item pairing."
  );
}


// ============================================================
// FINAL OUTPUT
// ============================================================

return [

  {

    json: {

      verification_status:
        "ready_for_fact_extraction",

      student_profile:
        studentProfile,

      college_count:
        colleges.length,

      colleges:
        colleges
    }

  }

];

// ============================================================
// EDUCOMPASS — FINAL STUDENT-FACING EXCEL
//
// Output:
// 10 ranked MBA colleges
// User-friendly selection checklist
// ============================================================

const result =
  $input.first()?.json || {};

const top10 =
  Array.isArray(result.top_10)
    ? result.top_10
    : [];

function clean(value) {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim();
}

function truncate(value, max = 500) {

  const text = clean(value);

  return text.length > max
    ? text.slice(0, max) + "..."
    : text;
}

function criterion(
  college,
  number
) {

  const criteria =
    college.criteria || {};

  return (
    criteria[String(number)] ||
    criteria[number] ||
    {}
  );
}

function criterionValue(
  college,
  number
) {

  const item =
    criterion(
      college,
      number
    );

  return item.value;
}

function textValue(
  college,
  number
) {

  const value =
    criterionValue(
      college,
      number
    );

  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  if (
    typeof value === "object"
  ) {

    return truncate(
      Object.entries(value)
        .map(
          ([key, val]) =>
            `${key}: ${
              Array.isArray(val)
                ? val.join(", ")
                : clean(val)
            }`
        )
        .join(" | ")
    );
  }

  return truncate(
    value
  );
}


// ------------------------------------------------------------
// Admission / cutoff
// ------------------------------------------------------------

function admissionData(
  college
) {

  const value =
    criterionValue(
      college,
      14
    );

  if (
    !value ||
    typeof value !== "object"
  ) {

    return {
      exams: "",
      cutoff2025: "",
      cutoff2024: "",
      eligibility: ""
    };
  }

  const exams =
    Array.isArray(
      value.accepted_exams
    )
      ? value.accepted_exams.join(
          ", "
        )
      : "";

  const history =
    Array.isArray(
      value.cutoff_history
    )
      ? value.cutoff_history
      : [];

  function cutoffForYear(year) {

    const rows =
      history.filter(
        row =>
          Number(
            row.year
          ) === year
      );

    return rows
      .map(
        row =>
          `${row.exam || ""}${
            row.exam ? ": " : ""
          }${row.percentile}%`
      )
      .join("; ");
  }

  const eligibility =
    textValue(
      college,
      14
    );

  return {
    exams,

    cutoff2025:
      cutoffForYear(2025),

    cutoff2024:
      cutoffForYear(2024),

    eligibility
  };
}


// ------------------------------------------------------------
// Placement
// ------------------------------------------------------------

function placementData(
  college
) {

  const value =
    criterionValue(
      college,
      4
    );

  if (
    !value ||
    typeof value !== "object"
  ) {

    return {
      average: "",
      median: "",
      highest: "",
      percentage: ""
    };
  }

  return {

    average:
      value.average_salary_lakh ??
      "",

    median:
      value.median_salary_lakh ??
      "",

    highest:
      value.highest_salary_lakh ??
      "",

    percentage:
      value.placement_percentage ??
      ""
  };
}


// ------------------------------------------------------------
// Recruiters
// ------------------------------------------------------------

function recruiterData(
  college
) {

  const value =
    criterionValue(
      college,
      6
    );

  if (!value) {
    return "";
  }

  if (
    typeof value === "string"
  ) {

    return truncate(
      value
    );
  }

  return truncate(
    JSON.stringify(value)
  );
}


// ------------------------------------------------------------
// Specializations
// ------------------------------------------------------------

function specializationData(
  college
) {

  const value =
    criterionValue(
      college,
      7
    );

  if (!value) {
    return "";
  }

  return truncate(
    value
  );
}


// ------------------------------------------------------------
// ROI
// ------------------------------------------------------------

function roiData(
  college
) {

  const value =
    criterionValue(
      college,
      5
    );

  if (
    !value ||
    typeof value !== "object"
  ) {

    return "";
  }

  const fee =
    Number(
      value.program_fee_lakh
    );

  const salary =
    Number(
      value.average_salary_lakh
    );

  if (
    !fee ||
    !salary
  ) {

    return (
      "Not enough verified fee and salary data"
    );
  }

  const multiple =
    salary / fee;

  return (
    `${multiple.toFixed(2)}x ` +
    `(₹${fee.toFixed(2)}L fee vs ` +
    `₹${salary.toFixed(2)}L average package)`
  );
}


// ------------------------------------------------------------
// Sources
// ------------------------------------------------------------

function sources(
  college
) {

  const evidence =
    Array.isArray(
      college.evidence
    )
      ? college.evidence
      : [];

  const urls =
    evidence
      .map(
        item =>
          clean(
            item.url
          )
      )
      .filter(Boolean);

  return [
    ...new Set(urls)
  ].join("\n");
}


// ------------------------------------------------------------
// Nearby hub
// ------------------------------------------------------------

function nearbyHub(
  college
) {

  const value =
    textValue(
      college,
      17
    );

  if (value) {
    return value;
  }

  const location =
    clean(
      college.location
    );

  if (!location) {
    return "Not publicly verified";
  }

  return (
    "Not publicly verified for this college"
  );
}


// ------------------------------------------------------------
// Data confidence
// ------------------------------------------------------------

function confidence(
  college
) {

  const coverage =
    Number(
      college.evidence_coverage
    );

  if (coverage >= 70) {
    return "High";
  }

  if (coverage >= 45) {
    return "Medium";
  }

  return "Limited";
}


// ------------------------------------------------------------
// FINAL OUTPUT
// ------------------------------------------------------------

return top10.map(
  college => {

    const admission =
      admissionData(
        college
      );

    const placement =
      placementData(
        college
      );

    return {
