// ============================================================
// EDUCOMPASS — AGENT 2 ONE-COLLEGE AUDIT PACKETS
//
// IMPORTANT:
// Output ONE n8n item per college.
//
// 12 colleges -> 12 Agent 2 calls.
//
// This keeps llama3.2:3b focused and fast.
// ============================================================

const input =
  $input.first()?.json || {};

const studentProfile =
  input.student_profile || {};

const candidates =
  Array.isArray(input.candidates)
    ? input.candidates
    : [];

function clean(value) {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim();
}

function compact(value, max = 280) {

  const text = clean(value);

  return text.length > max
    ? text.slice(0, max) + "..."
    : text;
}

const importantFields = [
  "Entrance Exams Accepted",
  "2025 Cutoff — Exam & Percentile",
  "2024 Cutoff — Exam & Percentile",
  "Total MBA Fees",
  "Average Placement Package",
  "Median Placement Package",
  "Placement Percentage",
  "Top Recruiting Companies",
  "Eligibility & Admission Criteria",
  "Reservation / Category Benefits"
];

return candidates.map(candidate => {

  const fields =
    candidate.fields || {};

  const compactFields = {};

  for (const field of importantFields) {

    const entries =
      Array.isArray(fields[field])
        ? fields[field]
        : [];

    compactFields[field] =
      entries
        .slice(0, 3)
        .map(entry => ({
          value:
            compact(entry.value),

          evidence:
            compact(entry.evidence),

          source_url:
            clean(entry.source_url),

          source_title:
            compact(
              entry.source_title,
              120
            ),

          source_type:
            clean(entry.source_type),

          scope:
            clean(entry.scope)
        }));
  }

  return {
    json: {

      audit_status:
        "ready_for_agent_2",

      student_profile:
        studentProfile,

      college: {

        candidate_index:
          candidate.candidate_index,

        institution:
          clean(
            candidate.institution
          ),

        program:
          clean(
            candidate.program
          ),

        location:
          clean(
            candidate.location
          ),

        selection_score:
          candidate.selection_score ??
          null,

        fields:
          compactFields
      },

      audit_rules: {

        source_priority:
          [
            "official",
            "secondary",
            "community"
          ],

        reject_if_wrong_college:
          true,

        reject_if_wrong_program:
          true,

        reject_wrong_exam:
          true,

        reject_wrong_year:
          true,

        preserve_scope:
          true,

        never_invent:
          true
      }

    }
  };
});
